pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    let mut out: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        if maxsplit == 0 {
            // No splitting at all
            out.push(vec![s]);
            continue;
        }

        if s.is_empty() {
            // Must produce a single empty string
            out.push(vec![String::new()]);
            continue;
        }

        // Perform up to `maxsplit` right splits, like Python's str.rsplit(sep, maxsplit).
        // We build parts from right to left, then reverse to restore left-to-right order.
        let mut parts_rev: Vec<String> = Vec::new();
        let mut remaining: &str = &s;
        let mut splits_done: u8 = 0;

        while splits_done < maxsplit {
            if let Some(pos) = remaining.rfind(&sep) {
                let after = &remaining[pos + sep.len()..];
                parts_rev.push(after.to_string());
                remaining = &remaining[..pos];
                splits_done += 1;
            } else {
                break;
            }
        }

        parts_rev.push(remaining.to_string()); // leftmost remainder (possibly empty)
        parts_rev.reverse();

        // Ensure inner list non-empty (it always is, due to push above)
        out.push(parts_rev);
    }

    out
}